#pragma once
#include "CadDocument.h"
#include "SketchGeometry.h"
#include <QDir>
#include <QFile>
#include <QJsonDocument>
#include <cmath>
#include <numbers>
namespace MultiFaceFixtures {
inline void check(bool pass,const QString& reason){if(!pass)throw std::runtime_error(reason.toStdString());}
inline QJsonObject accepted(const SketchGeometry::SolveResult& r){check(r.ok,r.error);return r.feature;}
inline void commit(CadDocument& d,const QJsonObject& a){const auto e=d.commit(a,"Gate fixture");check(e.isEmpty(),e);}
inline QJsonObject ref(const EvaluatedSupportFace& f){return {{"bodyId",f.bodyId},{"producerFeatureId",f.producerFeatureId},{"faceId",f.faceId}};}
inline QJsonObject box(CadDocument& d,const QString& name,double x,double y,double z,double w,double depth,double height){QJsonObject f{{"id",CadDocument::newId()},{"bodyId",CadDocument::newId()},{"ownerId",d.authored()["documentId"]},{"type","box"},{"name",name},{"visible",false},{"parameters",QJsonObject{{"xMm",x},{"yMm",y},{"zMm",z},{"widthMm",w},{"depthMm",depth},{"heightMm",height}}}};auto a=d.authored();auto rows=a["features"].toArray();rows.append(f);a["features"]=rows;commit(d,a);return f;}
inline QJsonObject rectangle(CadDocument& d,const QString& plane,double w,double h){auto f=SketchGeometry::newFeature(d.authored()["documentId"].toString(),plane,"Gate base");f=SketchGeometry::addRectangle(f,{{"u1Mm",0},{"v1Mm",0},{"u2Mm",w},{"v2Mm",h}});const auto e=f["parameters"].toObject()["entities"].toArray();f=accepted(SketchGeometry::addConstraint(f,{{"type","fixed"},{"pointIds",QJsonArray{e[0].toObject()["startPointId"]}}}));f=accepted(SketchGeometry::addDimension(f,{{"kind","horizontal"},{"entityId",e[0].toObject()["id"]},{"valueMm",w}}));f=accepted(SketchGeometry::addDimension(f,{{"kind","vertical"},{"entityId",e[1].toObject()["id"]},{"valueMm",h}}));commit(d,SketchGeometry::replaceFeature(d.authored(),f));return f;}
inline void prism(CadDocument& d,const QJsonObject& f,double distance){const auto& s=d.sketches().back();commit(d,CadDocument::extrusionCandidate(d.authored(),{{"sketchId",f["id"]},{"profileId",s.profiles[0].profileId},{"distanceMm",distance}}));}
inline QJsonObject create(const QString& folder){QDir().mkpath(folder);QJsonObject metadata;
    CadDocument plate;auto base=rectangle(plate,"XY",40,25);const auto width=base.value("parameters").toObject().value("dimensions").toArray().at(0).toObject().value("id");prism(plate,base,5);const auto target=plate.bodies()[0].bodyId;EvaluatedSupportFace cap;for(const auto& face:plate.bodies()[0].supportFaces)if(face.role=="extrude.endCap")cap=face;
    auto hole=SketchGeometry::newSupportedFeature(plate.authored()["documentId"].toString(),ref(cap),"Retained r3 hole",GeometryKernel::supportEdgeDescriptors(cap));hole=SketchGeometry::addCircle(hole,{{"centerUMm",30},{"centerVMm",12},{"diameterMm",6}});const auto c=hole["parameters"].toObject()["entities"].toArray()[0].toObject();const auto context=GeometryKernel::projectionContext(plate.evaluation(),hole);QString right,bottom;for(const auto& row:context["lines"].toArray()){const auto l=row.toObject();if(std::abs(l["u1Mm"].toDouble()-40)<1e-7 && std::abs(l["u2Mm"].toDouble()-40)<1e-7)right=l["id"].toString();if(std::abs(l["v1Mm"].toDouble())<1e-7 && std::abs(l["v2Mm"].toDouble())<1e-7)bottom=l["id"].toString();}
    for(const auto& offset:std::initializer_list<std::pair<QString,double>>{{right,5},{bottom,10}})hole=accepted(SketchGeometry::addDimension(hole,{{"kind","pointLineDistance"},{"pointIds",QJsonArray{c["centerPointId"]}},{"entityId",offset.first},{"valueMm",offset.second}},context));hole=accepted(SketchGeometry::addDimension(hole,{{"kind","radius"},{"entityId",c["id"]},{"valueMm",3}},context));commit(plate,SketchGeometry::replaceFeature(plate.authored(),hole));commit(plate,CadDocument::extrusionCandidate(plate.authored(),{{"sketchId",hole["id"]},{"profileId",plate.sketches().back().profiles[0].profileId},{"distanceMm",-5},{"operation","cut"},{"targetBodyIds",QJsonArray{target}}}));check(std::abs(plate.bodies()[0].summary["volumeMm3"].toDouble()-(5000-45*std::numbers::pi))<1e-5,"plate seed volume");check(plate.save(folder+"/plate40.alloy").isEmpty(),"plate seed save");metadata["plate"]=QJsonObject{{"baseSketchId",base["id"]},{"widthDimensionId",width},{"holeSketchId",hole["id"]},{"centerPointId",c["centerPointId"]},{"targetBodyId",target}};
    CadDocument wedge;auto f=SketchGeometry::newFeature(wedge.authored()["documentId"].toString(),"XZ","Inclined wedge");const double p[][2]={{0,0},{40,0},{40,20},{0,10},{0,0}};for(int i=0;i<4;++i)f=SketchGeometry::addLine(f,{{"u1Mm",p[i][0]},{"v1Mm",p[i][1]},{"u2Mm",p[i+1][0]},{"v2Mm",p[i+1][1]}});commit(wedge,SketchGeometry::replaceFeature(wedge.authored(),f));prism(wedge,f,5);check(std::abs(wedge.bodies()[0].summary["volumeMm3"].toDouble()-3000)<1e-5,"inclined wedge volume");check(wedge.save(folder+"/inclined.alloy").isEmpty(),"inclined seed save");metadata["inclined"]=QJsonObject{{"baseSketchId",f["id"]},{"extrudeFeatureId",wedge.authored()["features"].toArray().last().toObject()["id"]},{"targetBodyId",wedge.bodies()[0].bodyId}};
    CadDocument failure;auto stock=rectangle(failure,"XY",50,25);prism(failure,stock,5);const auto stockId=failure.bodies()[0].bodyId;auto notch=box(failure,"Notch tool",49,-1,2,2,27,4),split=box(failure,"Split tool",24,-1,2,2,27,4),deleted=box(failure,"Delete face tool",-1,-1,4,52,27,2);commit(failure,CadDocument::booleanCandidate(failure.authored(),{{"operation","cut"},{"targetBodyId",stockId},{"toolBodyIds",QJsonArray{notch["bodyId"]}},{"keepTools",true}}));const auto combine=failure.authored().value("features").toArray().last().toObject().value("id");EvaluatedSupportFace surviving;for(const auto& body:failure.bodies())if(body.bodyId==stockId)for(const auto& face:body.supportFaces)if(face.role=="extrude.endCap")surviving=face;check(!surviving.faceId.isEmpty(),"initial notch retains unique top support");auto attached=SketchGeometry::newSupportedFeature(failure.authored()["documentId"].toString(),ref(surviving),"Dependent failure sketch");attached=SketchGeometry::addCircle(attached,{{"centerUMm",5},{"centerVMm",5},{"diameterMm",3}});commit(failure,SketchGeometry::replaceFeature(failure.authored(),attached));check(failure.save(folder+"/support-failure.alloy").isEmpty(),"failure seed save");metadata["failure"]=QJsonObject{{"combineFeatureId",combine},{"targetBodyId",stockId},{"notchBodyId",notch["bodyId"]},{"splitBodyId",split["bodyId"]},{"deleteBodyId",deleted["bodyId"]},{"support",ref(surviving)},{"sketchId",attached["id"]}};
    QFile file(folder+"/fixtures.json");check(file.open(QIODevice::WriteOnly),"metadata file");file.write(QJsonDocument(metadata).toJson(QJsonDocument::Indented));return metadata;
}
}
